1	import { useQuery } from '@tanstack/react-query';
2	import { getJson } from '../../api/http';
3	
4	// The projects a client is doing work on, shown in the client's detail. Server data is read straight
5	// from the SHARED ['projects'] query key (CLAUDE.md rule 5) — the same key the Projects page uses —
6	// so creating a project anywhere refreshes this list too, with no import of the projects feature.
7	// Each project carries its clientId, so the client context is just a filter on that shared data.
8	type Project = { id: number; name: string; clientId: number; clientName: string };
9	
10	export function ClientProjects({ clientId }: { clientId: number }) {
11	  const { data: projects } = useQuery({
12	    queryKey: ['projects'] as const,
13	    queryFn: () => getJson<Project[]>('/api/projects'),
14	  });
15	
16	  if (!projects) {
17	    return null;
18	  }
19	
20	  const owned = projects.filter((project) => project.clientId === clientId);
21	
22	  if (owned.length === 0) {
23	    return <p data-testid="client-projects-empty">No projects for this client yet.</p>;
24	  }
25	
26	  // Reuse the project-row-<id>/project-name anchors inside the client-context table.
27	  return (
28	    <table data-testid="client-projects-table">
29	      <thead>
30	        <tr>
31	          <th>Name</th>
32	        </tr>
33	      </thead>
34	      <tbody>
35	        {owned.map((project) => (
36	          <tr key={project.id} data-testid={`project-row-${project.id}`}>
37	            <td data-testid="project-name">{project.name}</td>
