1	package net.officefloor.hq.app;
2	
3	import java.util.List;
4	import java.util.Map;
5	import org.springframework.context.annotation.Profile;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.web.bind.annotation.PostMapping;
8	import org.springframework.web.bind.annotation.RequestBody;
9	import org.springframework.web.bind.annotation.RequestMapping;
10	import org.springframework.web.bind.annotation.RestController;
11	
12	/**
13	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
14	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
15	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
16	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
17	 */
18	@Profile("harness")
19	@RestController
20	@RequestMapping("/__test__")
21	public class TestSupportController {
22	
23	    private final Audit audit;
24	    private final JdbcTemplate jdbc;
25	
26	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
27	        this.audit = audit;
28	        this.jdbc = jdbc;
29	    }
30	
31	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
32	    @PostMapping("/reset")
33	    public void reset() {
34	        audit.clear();
35	        // projects -> clients foreign key: H2 refuses TRUNCATE on a referenced table, so drop
36	        // referential integrity for the truncate and restore it immediately after.
37	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
38	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
39	        jdbc.execute("TRUNCATE TABLE invoice_line_items RESTART IDENTITY");
40	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
44	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
45	    }
46	
47	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
48	    @PostMapping("/seed")
49	    @SuppressWarnings("unchecked")
50	    public void seed(@RequestBody Map<String, Object> fixture) {
51	        // FIXTURE REPAIR 005: advance the clients IDENTITY past every explicitly seeded id
52	        // BEFORE inserting them. /reset does TRUNCATE ... RESTART IDENTITY, which sets the
53	        // sequence back to 1, and seeding an explicit id does not move it — so the next row
54	        // created through the UI is assigned an id that is already taken. H2 does not raise:
55	        // the insert silently becomes a no-op (200, empty body, no new row), which is why this
56	        // surfaced as "expected 2 rows, got 1" with nothing in any log.
57	        List<Map<String, Object>> seededClients = (List<Map<String, Object>>) fixture.get("clients");
58	        if (seededClients != null) {
59	            for (Map<String, Object> seeded : seededClients) {
60	                jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH "
61	                        + (((Number) seeded.get("id")).longValue() + 1));
62	            }
63	        }
64	        List<Map<String, Object>> clients = (List<Map<String, Object>>) fixture.get("clients");
65	        if (clients != null) {
66	            for (Map<String, Object> client : clients) {
67	                // Explicit fixture id (JPA save() would ignore it on an IDENTITY column).
68	                jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
69	                        ((Number) client.get("id")).longValue(), client.get("name"),
70	                        client.get("email"));
71	            }
72	        }
73	        List<Map<String, Object>> projects = (List<Map<String, Object>>) fixture.get("projects");
74	        if (projects != null) {
75	            for (Map<String, Object> project : projects) {
76	                jdbc.update("INSERT INTO projects (id, name, client_id) VALUES (?, ?, ?)",
77	                        ((Number) project.get("id")).longValue(), project.get("name"),
78	                        ((Number) project.get("clientId")).longValue());
79	            }
80	        }
81	        List<Map<String, Object>> contacts = (List<Map<String, Object>>) fixture.get("contacts");
82	        if (contacts != null) {
83	            for (Map<String, Object> contact : contacts) {
84	                jdbc.update("INSERT INTO contacts (id, client_id, name, email, contact_role)"
85	                        + " VALUES (?, ?, ?, ?, ?)",
86	                        ((Number) contact.get("id")).longValue(),
87	                        ((Number) contact.get("clientId")).longValue(), contact.get("name"),
88	                        contact.get("email"), contact.get("role"));
89	            }
90	        }
91	        List<Map<String, Object>> tasks = (List<Map<String, Object>>) fixture.get("tasks");
92	        if (tasks != null) {
93	            for (Map<String, Object> task : tasks) {
94	                // done is optional in a fixture; default to false (OPEN) when absent.
95	                Object done = task.get("done");
96	                jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
97	                        ((Number) task.get("id")).longValue(),
98	                        ((Number) task.get("projectId")).longValue(), task.get("title"),
99	                        done != null && Boolean.parseBoolean(done.toString()));
100	            }
101	        }
102	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
103	        if (invoices != null) {
104	            for (Map<String, Object> invoice : invoices) {
105	                // status is optional in a fixture; default to UNPAID (matching Flyway V5) when absent.
106	                Object status = invoice.get("status");
107	                // issuedDate/dueDate are optional; fall back to the Flyway V7 column defaults when absent.
108	                Object issuedDate = invoice.get("issuedDate");
109	                Object dueDate = invoice.get("dueDate");
110	                // An invoice is built from line items (Flyway V13). Its amount is the worked-out sum
111	                // of qty * unitPrice across them (zero when there are none yet) — a fixture no longer
112	                // types a figure, it lists what is charged. (An explicit `amount` still wins if a
113	                // fixture gives one, for back-compatibility with lump-sum invoices.)
114	                List<Map<String, Object>> lineItems =
115	                        (List<Map<String, Object>>) invoice.get("lineItems");
116	                java.math.BigDecimal amount = java.math.BigDecimal.ZERO;
117	                if (lineItems != null) {
118	                    for (Map<String, Object> line : lineItems) {
119	                        java.math.BigDecimal unitPrice =
120	                                new java.math.BigDecimal(line.get("unitPrice").toString());
121	                        int qty = ((Number) line.get("qty")).intValue();
122	                        amount = amount.add(unitPrice.multiply(java.math.BigDecimal.valueOf(qty)));
123	                    }
124	                }
125	                if (invoice.get("amount") != null) {
126	                    amount = new java.math.BigDecimal(invoice.get("amount").toString());
127	                }
128	                long invoiceId = ((Number) invoice.get("id")).longValue();
129	                jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
130	                        + " VALUES (?, ?, ?, ?, COALESCE(?, CURRENT_DATE),"
131	                        + " COALESCE(?, DATEADD('DAY', 30, CURRENT_DATE)))",
132	                        invoiceId,
133	                        ((Number) invoice.get("projectId")).longValue(),
134	                        amount,
135	                        status != null ? status.toString() : "UNPAID",
136	                        issuedDate != null ? java.sql.Date.valueOf(issuedDate.toString()) : null,
137	                        dueDate != null ? java.sql.Date.valueOf(dueDate.toString()) : null);
138	                if (lineItems != null) {
139	                    for (Map<String, Object> line : lineItems) {
140	                        jdbc.update("INSERT INTO invoice_line_items"
141	                                + " (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
142	                                ((Number) line.get("id")).longValue(), invoiceId,
143	                                line.get("description"), ((Number) line.get("qty")).intValue(),
144	                                new java.math.BigDecimal(line.get("unitPrice").toString()));
145	                    }
146	                }
147	            }
148	        }
149	    }
150	}
